from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    distinct_segments = []  # Initialize an empty list to store the distinct segments
    stack = []  # Stack to keep track of opening and closing parentheses

    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                distinct_segments.append(paren_string[start:i+1])

    return distinct_segments

